    static let signatureTalents: [String: CombatantTalentEffect] = {
        var combined: [String: CombatantTalentEffect] = [:]
        combined.reserveCapacity(364)
        for group in [
            knightTalents,
            rangerTalents,
            rogueTalents,
            wizardTalents,
            warlockTalents,
            wolfTalents,
            bearTalents,
            frostWhelpTalents,
            lizardScoutTalents,
            pantherTalents,
            phoenixTalents,
            goldenRetrieverTalents,
            libraryOwlTalents,
            risenSkeletonTalents,
            manaMothTalents,
            pixieTalents,
            shieldScarabTalents,
            foxTalents
        ] {
            for (key, value) in group {
                combined[key] = value
            }
        }
        return combined
    }()
